SELECT item_name,string_agg(distinct category_name,' | ') categories,min(trading_date),max(trading_date),count(*) FROM canonical_sale_item WHERE superseded_at IS NULL AND regexp_replace(btrim(regexp_replace(lower(item_name),'[^a-z0-9]+',' ','g')),'^new ','') IN('gnocchi pumpkin butter sage','gnocchi bolognese','fish tostada','four pillars gin martini','b moorak blanc de blanc','glenfiddich 30ml','b stargazer tupelo gris 2025','b chalmers vermentino 2025','manhattan','makers mark 30ml','amaretto 30ml','dill aioli','red wine jus side') GROUP BY 1 ORDER BY 1;
SELECT scope,source_system,entity_key,effective_from,sales_nature,reason FROM product_reporting_mapping WHERE entity_key IN ('site:0:code:8:20161229','site:0:code:8:21162117','site:0:code:8:23673809','site:0:code:8:19989720','site:0:code:8:22857471','site:0:code:8:12027390','site:0:code:8:23643649','site:0:code:8:23562304','site:0:code:8:17878130','site:0:code:8:12027397','site:0:code:8:17914368','site:0:code:8:22510826','site:0:code:8:20824947') ORDER BY id;
